// Independent PLAY-04 fix re-audit: real gateway child, real PostgreSQL, real stock match clients and real time.
// In each opening step the waiting player repeatedly presses the ordinary concede intent (stock client, sequential);
// the active player submits its opening decision after a randomized 300-700 ms delay. Repeated over 8 matches.
import { qualification, until } from './apps/match-service/tests/client-fixtures.mjs';

const clock = { schemaVersion: 1, id: 'audit-spam', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0 };
const trials = [];
const errors = [];
for (let match = 0; match < 8; match++) {
  let f;
  try {
    f = await qualification('http://localhost:5173', { clock });
    const host = await f.host(), clients = f.players.map((_, i) => f.client(i, host.url, { retryBaseMs: 250 }));
    await Promise.all(clients.map(c => c.connect()));
    for (let step = 0; step < 3; step++) {
      const active = f.players.indexOf(clients[0].view.priorityId), waiting = 1 - active;
      const intent = step === 0 ? { kind: 'chooseWhoGoesFirst', input: { playerId: f.players[0] } } : { kind: 'alterHand', input: { cardsToMulligan: [] } };
      let stop = false; const spam = {};
      const attacker = (async () => {
        while (!stop) {
          try { await until(() => stop || clients[waiting].status === 'ready', 5000); } catch { spam.notReady = (spam.notReady ?? 0) + 1; break; }
          if (stop) break;
          const x = await clients[waiting].submit({ kind: 'concede', input: {} }).then(r => r.outcome + '/' + r.reason, e => 'client ' + e.code);
          spam[x] = (spam[x] ?? 0) + 1; if (x.startsWith('client closed')) break;
        }
      })();
      const startDelay = 300 + Math.floor(Math.random() * 400);
      await new Promise(r => setTimeout(r, startDelay));
      await until(() => clients[active].status === 'ready', 5000);
      const start = f.receipts[active].length, t0 = performance.now();
      const outcome = await clients[active].submit(intent).then(r => r.outcome, e => 'client ' + e.code);
      const elapsedMs = Math.round(performance.now() - t0); stop = true; await attacker;
      trials.push({ match, step, startDelay, outcome, elapsedMs, activeBusyReceipts: f.receipts[active].slice(start).filter(r => r.outcome === 'rate_limited').length, waitingConcessions: spam });
      if (outcome !== 'accepted') break;
      await until(() => clients.every(c => c.status === 'ready' && c.view?.stateVersion >= step + 1), 10000);
    }
  } catch (error) { errors.push(String(error && error.stack || error)); } finally { if (f) await f.close().catch(e => errors.push('close ' + e)); }
}
const busy = trials.map(t => t.activeBusyReceipts);
console.log(JSON.stringify({
  steps: trials.length,
  stepsWithBusy: busy.filter(b => b > 0).length,
  totalActiveBusyReceipts: busy.reduce((a, b) => a + b, 0),
  activeClientClosed: trials.filter(t => t.outcome !== 'accepted').length,
  maxActiveDelayMs: Math.max(...trials.map(t => t.elapsedMs)),
  waitingConcessionReceipts: trials.reduce((acc, t) => { for (const [k, v] of Object.entries(t.waitingConcessions)) acc[k] = (acc[k] ?? 0) + v; return acc; }, {}),
  trials, errors,
}, null, 1));
